package app.yoru.mobile;

import android.app.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.text.*;
import java.util.*;

public final class CalendarScreen extends ScrollView {
    private static final int DAYS=21;
    private static final String[][] FILTERS={{"all","Все"},{"fav","Избранное"},{"new","Новые для меня"},{"soon","Скоро"},{"premiere","Премьеры"},{"ongoing","Выходит"},{"film","Фильмы"}};
    private final Activity activity;private final LinearLayout body,dayRow,filterRow,list;private final TextView state,heroTitle,heroMeta;private final ArrayList<ApiRepository.AiringItem> items=new ArrayList<>();private final HashMap<String,ArrayList<ArrayList<ApiRepository.AiringItem>>> buckets=new HashMap<>();private final Locale ru=new Locale("ru");private final long[] starts=new long[DAYS];private final String[] shortDays=new String[DAYS],longDays=new String[DAYS];private int selected,generation;private String filter="all";private boolean attached;
    public CalendarScreen(Activity a){super(a);activity=a;attached=true;setFillViewport(true);prepareDays();body=Ui.column(a);body.setPadding(Ui.dp(a,18),Ui.dp(a,14),Ui.dp(a,18),Ui.dp(a,30));addView(body,new ScrollView.LayoutParams(-1,-2));body.addView(Ui.label(a,"КАЛЕНДАРЬ YORU"));Ui.space(body,11);body.addView(Ui.text(a,"Выход серий",29,Ui.TEXT,true));Ui.space(body,9);body.addView(Ui.text(a,"Онгоинги, премьеры и ближайшие серии с точными датами выхода, когда они доступны.",12,Ui.MUTED,false));Ui.space(body,17);LinearLayout hero=Ui.column(a);hero.setPadding(Ui.dp(a,18),Ui.dp(a,18),Ui.dp(a,18),Ui.dp(a,18));hero.setBackground(Ui.gradient(0xff2e2140,0xff181220,20,a));heroTitle=Ui.text(a,"Открываем календарь…",21,Ui.TEXT,true);hero.addView(heroTitle);Ui.space(hero,8);heroMeta=Ui.text(a,"YORU готовит быстрые фильтры",12,0xffd8c7ea,false);hero.addView(heroMeta);Ui.space(hero,13);hero.addView(Ui.button(a,"Обновить календарь",false,this::load));body.addView(hero,Ui.lp(a,-1,-2));Ui.space(body,17);HorizontalScrollView days=new HorizontalScrollView(a);days.setHorizontalScrollBarEnabled(false);dayRow=Ui.row(a);days.addView(dayRow);body.addView(days,Ui.lp(a,-1,-2));Ui.space(body,10);HorizontalScrollView filters=new HorizontalScrollView(a);filters.setHorizontalScrollBarEnabled(false);filterRow=Ui.row(a);filters.addView(filterRow);body.addView(filters,Ui.lp(a,-1,-2));Ui.space(body,14);state=Ui.text(a,"",12,Ui.MUTED,false);body.addView(state);Ui.space(body,12);list=Ui.column(a);body.addView(list);load();}
    @Override protected void onAttachedToWindow(){super.onAttachedToWindow();attached=true;}
    @Override protected void onDetachedFromWindow(){attached=false;super.onDetachedFromWindow();}
    private void load(){int gen=++generation;prepareDays();ArrayList<ApiRepository.AiringItem> cached=unpack(YoruApp.app().store.calendarCache());if(!cached.isEmpty()){setItems(cached);state.setText("Календарь открыт сразу · обновляем даты");}else{state.setText("Обновляем календарь…");heroTitle.setText("YORU следит за неделей");heroMeta.setText("Даты появятся сразу после ответа расписания.");list.removeAllViews();progressCard();renderFilters();renderDays();}YoruApp.app().io.execute(()->{try{ArrayList<ApiRepository.AiringItem> loaded=YoruApp.app().api.airingSchedule(DAYS,YoruApp.app().store.favorites());YoruApp.app().main.post(()->{if(!alive()||gen!=generation)return;setItems(loaded);YoruApp.app().store.calendarCache(pack(loaded));});}catch(Exception e){YoruApp.app().main.post(()->{if(!alive()||gen!=generation)return;if(items.isEmpty()){if(!cached.isEmpty()){setItems(cached);state.setText("Показан сохранённый календарь. Свежие даты пока не ответили.");}else{list.removeAllViews();state.setText("Календарь временно недоступен");emptyCard("Календарь временно недоступен","YORU продолжает работать. Нажмите “Обновить календарь”, когда сеть стабилизируется.");}}else state.setText("Сохранённый календарь открыт · свежие даты пока недоступны");});}});}
    public void quickShow(){prepareDays();if(items.isEmpty()){ArrayList<ApiRepository.AiringItem> cached=unpack(YoruApp.app().store.calendarCache());if(!cached.isEmpty())setItems(cached);else{renderFilters();renderDays();}}}
    private boolean alive(){return attached&&!activity.isFinishing();}
    private void setItems(List<ApiRepository.AiringItem> rows){items.clear();if(rows!=null)items.addAll(rows);buildBuckets();if(dayItems(selected).isEmpty())selected=firstDayWithEvents();renderFilters();renderDays();renderList();}
    private void buildBuckets(){buckets.clear();for(String[] f:FILTERS){ArrayList<ArrayList<ApiRepository.AiringItem>> days=new ArrayList<>(DAYS);for(int i=0;i<DAYS;i++)days.add(new ArrayList<>());buckets.put(f[0],days);}long now=System.currentTimeMillis();for(ApiRepository.AiringItem item:items){if(item==null||item.anime==null)continue;int day=(int)((startOfDay(item.time)-starts[0])/(24L*60*60*1000));if(day<0||day>=DAYS)continue;boolean fav=YoruApp.app().store.favorite(item.anime);boolean history=YoruApp.app().store.progress(item.anime).length()>0;boolean premiere="Премьера".equals(item.kind);boolean ongoing=item.anime.ongoing()||"Новая серия".equals(item.kind);boolean film=item.anime.type.toLowerCase(Locale.ROOT).contains("фильм");addBucket("all",day,item);if(fav)addBucket("fav",day,item);if(!history&&!fav)addBucket("new",day,item);if(item.time>=now)addBucket("soon",day,item);if(premiere)addBucket("premiere",day,item);if(ongoing)addBucket("ongoing",day,item);if(film)addBucket("film",day,item);}}
    private void addBucket(String key,int day,ApiRepository.AiringItem item){ArrayList<ArrayList<ApiRepository.AiringItem>> days=buckets.get(key);if(days!=null&&day>=0&&day<days.size())days.get(day).add(item);}
    private ArrayList<ApiRepository.AiringItem> dayItems(int day){ArrayList<ArrayList<ApiRepository.AiringItem>> days=buckets.get(filter);if(days==null||day<0||day>=days.size())return new ArrayList<>();return days.get(day);}
    private void renderDays(){dayRow.removeAllViews();for(int i=0;i<DAYS;i++){final int index=i;TextView chip=Ui.chip(activity,shortDays[i]+" · "+dayItems(i).size(),i==selected,()->{if(selected==index)return;selected=index;renderDays();renderList();});LinearLayout.LayoutParams p=Ui.lp(activity,-2,-2);p.rightMargin=Ui.dp(activity,7);dayRow.addView(chip,p);}}
    private void renderFilters(){filterRow.removeAllViews();for(String[] r:FILTERS){TextView chip=Ui.chip(activity,r[1],r[0].equals(filter),()->{if(r[0].equals(filter))return;filter=r[0];selected=firstDayWithEvents();renderFilters();renderDays();renderList();});LinearLayout.LayoutParams p=Ui.lp(activity,-2,-2);p.rightMargin=Ui.dp(activity,7);filterRow.addView(chip,p);}}
    private void renderList(){list.removeAllViews();ArrayList<ApiRepository.AiringItem> day=dayItems(selected);String title=day.isEmpty()?"На этот день пока пусто":nearestTitle();int filtered=filteredCount();heroTitle.setText(title);heroMeta.setText(items.isEmpty()?"Нет данных календаря":filtered+" событий по текущему фильтру · "+exactCount()+" с точным временем");state.setText(longDays[selected]+(day.isEmpty()?" · новых серий не найдено":" · событий: "+day.size()));if(day.isEmpty()){emptyForFilter();return;}for(int i=0;i<day.size();i++)itemCard(day.get(i));}
    private void itemCard(ApiRepository.AiringItem item){LinearLayout card=Ui.row(activity);card.setGravity(Gravity.CENTER_VERTICAL);card.setPadding(Ui.dp(activity,12),Ui.dp(activity,12),Ui.dp(activity,12),Ui.dp(activity,12));card.setBackground(Ui.stroke(Ui.CARD,16,activity));ImageView poster=new ImageView(activity);poster.setScaleType(ImageView.ScaleType.CENTER_CROP);poster.setBackground(Ui.shape(Ui.SURFACE,12,activity));poster.setClipToOutline(true);card.addView(poster,Ui.lp(activity,54,76));if(item.anime!=null)YoruApp.app().images.load(poster,item.anime);LinearLayout text=Ui.column(activity);text.setPadding(Ui.dp(activity,12),0,0,0);TextView name=Ui.text(activity,item.anime==null?"Аниме":item.anime.title,14,Ui.TEXT,true);name.setMaxLines(2);name.setEllipsize(android.text.TextUtils.TruncateAt.END);text.addView(name);Ui.space(text,6);text.addView(Ui.text(activity,item.kind+" · серия "+item.episode+" · "+time(item.time),11,Ui.PURPLE,true));Ui.space(text,5);text.addView(Ui.text(activity,countdown(item.time)+" · "+item.precision,10,Ui.MUTED,false));card.addView(text,new LinearLayout.LayoutParams(0,-2,1));Ui.Icon icon=new Ui.Icon(activity,"play");icon.color=Ui.PURPLE;card.addView(icon,Ui.lp(activity,24,24));Ui.press(card);card.setOnClickListener(v->{if(item.anime!=null)Ui.openDetails(activity,item.anime);});LinearLayout.LayoutParams cp=Ui.lp(activity,-1,-2);cp.bottomMargin=Ui.dp(activity,9);list.addView(card,cp);}
    private void progressCard(){LinearLayout c=Ui.column(activity);c.setPadding(Ui.dp(activity,16),Ui.dp(activity,16),Ui.dp(activity,16),Ui.dp(activity,16));c.setGravity(Gravity.CENTER_HORIZONTAL);c.setBackground(Ui.stroke(Ui.CARD,16,activity));ProgressBar bar=new ProgressBar(activity);c.addView(bar,Ui.lp(activity,36,36));Ui.space(c,12);c.addView(Ui.text(activity,"Собираем ближайшие релизы…",12,Ui.MUTED,true));list.addView(c,Ui.lp(activity,-1,-2));}
    private void emptyCard(String title,String message){LinearLayout c=Ui.column(activity);c.setPadding(Ui.dp(activity,16),Ui.dp(activity,16),Ui.dp(activity,16),Ui.dp(activity,16));c.setBackground(Ui.stroke(Ui.CARD,16,activity));c.addView(Ui.text(activity,title,17,Ui.TEXT,true));Ui.space(c,8);c.addView(Ui.text(activity,message,12,Ui.MUTED,false));list.addView(c,Ui.lp(activity,-1,-2));}
    private int firstDayWithEvents(){for(int i=0;i<DAYS;i++)if(!dayItems(i).isEmpty())return i;return Math.max(0,Math.min(DAYS-1,selected));}
    private int filteredCount(){int n=0;ArrayList<ArrayList<ApiRepository.AiringItem>> days=buckets.get(filter);if(days!=null)for(ArrayList<ApiRepository.AiringItem> d:days)n+=d.size();return n;}
    private int exactCount(){int n=0;ArrayList<ArrayList<ApiRepository.AiringItem>> days=buckets.get(filter);if(days!=null)for(ArrayList<ApiRepository.AiringItem> d:days)for(ApiRepository.AiringItem item:d)if("Точная дата".equals(item.precision)||"Премьера".equals(item.precision))n++;return n;}
    private String nearestTitle(){long now=System.currentTimeMillis();ApiRepository.AiringItem best=null,past=null;ArrayList<ArrayList<ApiRepository.AiringItem>> days=buckets.get(filter);if(days!=null)for(ArrayList<ApiRepository.AiringItem> d:days)for(ApiRepository.AiringItem item:d){if(item.time>=now&&(best==null||item.time<best.time))best=item;if(item.time<now&&(past==null||item.time>past.time))past=item;}if(best==null)best=past;return best==null?"Календарь YORU":(best.time<System.currentTimeMillis()?"Уже вышло: ":"Ближайшая серия: ")+(best.anime==null?"аниме":best.anime.title);}
    private void emptyForFilter(){if("fav".equals(filter)){int fav=YoruApp.app().store.favoriteCount();emptyCard(fav>0?"В избранном пока нет дат":"Избранное пустое",fav>0?"YORU проверяет избранные тайтлы через расписание Shikimori. Если точной даты ещё нет у расписания, она появится после обновления.":"Добавьте онгоинг в коллекцию, и календарь будет показывать дату новой серии здесь.");return;}emptyCard("Тихий день","Проверьте соседние дни или обновите календарь. У части онгоингов дата может появиться ближе к релизу.");}
    private void prepareDays(){long base=todayStart();for(int i=0;i<DAYS;i++){starts[i]=base+i*24L*60*60*1000;shortDays[i]=i==0?"Сегодня":i==1?"Завтра":new SimpleDateFormat("EEE dd.MM",ru).format(new Date(starts[i])).replaceFirst("\\.","");longDays[i]=i==0?"Сегодня":i==1?"Завтра":new SimpleDateFormat("EEEE, dd MMMM",ru).format(new Date(starts[i]));}}
    private long todayStart(){Calendar c=Calendar.getInstance();c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);return c.getTimeInMillis();}
    private long startOfDay(long t){Calendar c=Calendar.getInstance();c.setTimeInMillis(t);c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);return c.getTimeInMillis();}
    private String time(long t){return new SimpleDateFormat("HH:mm",ru).format(new Date(t));}
    private JSONArray pack(List<ApiRepository.AiringItem> rows){JSONArray arr=new JSONArray();try{for(ApiRepository.AiringItem item:rows){if(item==null||item.anime==null)continue;arr.put(new JSONObject().put("anime",item.anime.json()).put("time",item.time).put("episode",item.episode).put("kind",item.kind).put("precision",item.precision).put("source",item.source));}}catch(Exception ignored){}return arr;}
    private ArrayList<ApiRepository.AiringItem> unpack(String text){ArrayList<ApiRepository.AiringItem> out=new ArrayList<>();try{JSONArray arr=new JSONArray(text);for(int i=0;i<arr.length()&&i<600;i++){JSONObject j=arr.optJSONObject(i);if(j==null)continue;ApiRepository.AiringItem item=new ApiRepository.AiringItem();item.anime=Anime.from(j.optJSONObject("anime"));item.time=j.optLong("time");item.episode=j.optInt("episode");item.kind=j.optString("kind");item.precision=j.optString("precision");item.source=j.optString("source");if(Anime.valid(item.anime)&&item.time>0)out.add(item);}}catch(Exception ignored){}return out;}
    private String countdown(long t){long diff=t-System.currentTimeMillis();if(diff<=-90*60*1000)return "уже вышло";if(diff<=0)return "выходит сейчас";long min=diff/60000,h=min/60,d=h/24;if(d>0)return "через "+d+" д "+(h%24)+" ч";if(h>0)return "через "+h+" ч "+(min%60)+" мин";return "через "+Math.max(1,min)+" мин";}
}
